import type { TableSource } from './wago.ts';

// One generated file. generate() reads the game tables it needs and returns
// the file's contents; output is relative to the repository root.
export interface Dataset {
  name: string;
  description: string;
  output: string;
  generate(tables: TableSource, build: string): Promise<string>;
}

// A fact Map.db2 and friends do not carry, kept with where it came from.
export interface Curated<T> {
  value: T;
  source: string;
  note?: string;
}

export function generatedHeader(dataset: Dataset, build: string, tables: string[]): string[] {
  return [
    `Generated by packages/game-data (dataset "${dataset.name}") from World of Warcraft: Forever`,
    `build ${build} game tables (${tables.join(', ')}) via wago.tools. Do not edit: run`,
    `pnpm data:generate after a patch. ${dataset.description}`,
  ];
}
